import type {HandoffScope} from './cashier-handoff';
export type BankDebitSelection={scope:HandoffScope;statement:string;mapping:string;expense:string;bank:string;amount:string;period:string;date:string};
const uuid=(v:unknown):v is string=>typeof v==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(v);
function obj(v:unknown):Record<string,unknown>{if(!v||typeof v!=='object'||Array.isArray(v))throw Error('Invalid bank debit preview.');return v as Record<string,unknown>}
function date(v:unknown):v is string{return typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v))&&new Date(v).toISOString().slice(0,10)===v}
export function readBankDebitPreview(value:unknown,s:BankDebitSelection){const v=obj(value),c=obj(v.command);
 if(![...Object.values(s.scope),s.statement,s.mapping,s.expense,s.bank,s.period].every(uuid)||s.expense===s.bank||!date(s.date)||! /^[1-9][0-9]{0,11}$/.test(s.amount))throw Error('Invalid bank debit selection.');
 if(v.schema_version!==1||v.tenant_id!==s.scope.tenant||v.property_id!==s.scope.property||v.actor_id!==s.scope.actor||v.statement_id!==s.statement||v.mapping_id!==s.mapping||v.expense_account_id!==s.expense||v.amount_minor!==s.amount||v.period_id!==s.period||v.posting_date!==s.date||!date(v.statement_value_date)||s.date<v.statement_value_date||v.bank_verified!==false||v.journal_posted!==false)throw Error('Bank debit preview changed.');
 if(c.currency!=='USD'||c.description!=='Bank debit expense'||c.source_kind!=='cashier_bank_debit'||c.source_id!==s.statement||c.source_version!==1||c.period_id!==s.period||c.posting_date!==s.date||!Array.isArray(c.lines)||c.lines.length!==2)throw Error('Invalid bank debit command.');
 const debit=obj(c.lines[0]),credit=obj(c.lines[1]);if(debit.account_id!==s.expense||credit.account_id!==s.bank||debit.side!=='debit'||credit.side!=='credit'||debit.amount_minor!==s.amount||credit.amount_minor!==s.amount)throw Error('Bank debit accounts or amounts changed.');return v;
}
export type BankDebitRequest={id:string;selection:BankDebitSelection;review:Record<string,unknown>};
function checked(r:BankDebitRequest){if(!uuid(r.id))throw Error('Invalid bank debit request.');readBankDebitPreview(r.review,r.selection);return r}
export function readBankDebitReceipt(value:unknown,r:BankDebitRequest){checked(r);const v=obj(value),s=r.selection;if(v.schema_version!==1||v.tenant_id!==s.scope.tenant||v.property_id!==s.scope.property||v.actor_id!==s.scope.actor||v.request_id!==r.id||v.statement_id!==s.statement||v.amount_minor!==s.amount||!uuid(v.journal_id)||typeof v.replayed!=='boolean'||v.journal_posted!==true||v.verifies_settlement!==false)throw Error('Settlement receipt does not match the saved request.');return v}
function canonical(value:unknown):string{if(Array.isArray(value))return '['+value.map(canonical).join(',')+']';if(value&&typeof value==='object')return '{'+Object.entries(value).sort(([a],[b])=>a.localeCompare(b)).map(([k,v])=>JSON.stringify(k)+':'+canonical(v)).join(',')+'}';return JSON.stringify(value)}
export function readBankDebitStatus(value:unknown,r:BankDebitRequest){checked(r);const v=obj(value),s=r.selection.scope;if(v.schema_version!==1||v.tenant_id!==s.tenant||v.property_id!==s.property||v.actor_id!==s.actor||v.request_id!==r.id||typeof v.found!=='boolean'||typeof v.cancelled!=='boolean'||typeof v.journal_reversed!=='boolean'||(v.found&&v.cancelled))throw Error('Settlement recovery scope changed.');if(!v.found){if(v.result!==null||v.review!==null||v.journal_reversed)throw Error('Invalid bank debit recovery.');return {state:v.cancelled?'cancelled' as const:'missing' as const,result:null,reversed:false}}if(canonical(v.review)!==canonical(r.review))throw Error('Recovered bank debit has a different review.');return {state:'posted' as const,result:readBankDebitReceipt(v.result,r),reversed:v.journal_reversed}}
type Store=Pick<Storage,'getItem'|'setItem'|'removeItem'>;
function storageKey(scope:HandoffScope,statement:string){if(![...Object.values(scope),statement].every(uuid))throw Error('Invalid bank debit storage scope.');return 'irp.bank.debit.v1:'+[scope.tenant,scope.property,scope.actor].join(':')+':'+statement}
export function retainBankDebit(store:Store,r:BankDebitRequest){checked(r);const key=storageKey(r.selection.scope,r.selection.statement),prior=store.getItem(key);if(prior!==null&&canonical(JSON.parse(prior))!==canonical(r))throw Error('Recover or cancel the previous bank debit first.');store.setItem(key,JSON.stringify(r));if(store.getItem(key)!==JSON.stringify(r))throw Error('Unable to retain bank debit request.');}
export function restoreBankDebit(store:Store,scope:HandoffScope,statement:string){const raw=store.getItem(storageKey(scope,statement));if(raw===null)return null;const r=JSON.parse(raw) as BankDebitRequest;checked(r);if(canonical(r.selection.scope)!==canonical(scope)||r.selection.statement!==statement)throw Error('Saved bank debit belongs to another workspace.');return r}
export function clearBankDebit(store:Store,r:BankDebitRequest,status:unknown){const parsed=readBankDebitStatus(status,r);if(parsed.state==='missing')throw Error('Check or cancel the bank debit before clearing it.');const key=storageKey(r.selection.scope,r.selection.statement),prior=restoreBankDebit(store,r.selection.scope,r.selection.statement);if(prior&&canonical(prior)!==canonical(r))throw Error('Saved bank debit changed.');store.removeItem(key);return parsed}
